// Backwards compatibility alias
export const CATEGORY_GROUPS = PARENT_CATEGORIES

export function getCategorizedProducts(): CategorizedSection[] {
  return PARENT_CATEGORIES.map((parent) => {
    const subcategories = parent.subcategories.map((sub) => {
      const subProducts = sub.slugs
        .map((slug) => getProductBySlug(slug))
        .filter((p): p is Product => Boolean(p))
      return {
        ...sub,
        products: subProducts
      }
    })
    const allParentProducts = subcategories.flatMap((s) => s.products)
    return {
      ...parent,
      totalCount: allParentProducts.length,
      subcategories,
      products: allParentProducts
    }
  })
}
